parameters.jsCode:
// Validate webhook input.
//
// Trigger contexts (any of):
//   - Operator clicks 'Publish' in Appsmith UI; UI posts here AFTER
//     aisha_publish_static_defense_rule RPC succeeds
//   - Aisha autonomous loop after publish RPC
//
// Payload shape: { rule_id: string, action: 'published' | 'deprecated',
//                  approver?: string }
//
// Output: enriched payload for downstream nodes

// ⛔ GitHub cíl se NEHÁDÁ: bez deklarovaného GITHUB_REPOSITORY (owner/repo) a
// https GITHUB_API_URL workflow odmítne commitovat — dosazené repo by zapisovalo
// do cizího repozitáře.
const githubRepository = String($env.GITHUB_REPOSITORY || '').trim();
if (!/^[A-Za-z0-9][A-Za-z0-9-]*\/[A-Za-z0-9_.-]+$/.test(githubRepository)) {
  throw new Error('GITHUB_REPOSITORY not configured (owner/repo) — refusing to commit to a guessed repository');
}
if (!String($env.GITHUB_API_URL || '').startsWith('https://')) {
  throw new Error('GITHUB_API_URL not configured (https)');
}

const body = $input.first().json.body || $input.first().json;
const ruleId = body.rule_id;
const action = body.action;
const approver = body.approver;

if (!ruleId || typeof ruleId !== 'string') {
  throw new Error('rule_id required (string)');
}
if (!['published', 'deprecated'].includes(action)) {
  throw new Error("action must be 'published' or 'deprecated' (got: " + action + ')');
}
if (!/^[a-z][a-z0-9-]+$/.test(ruleId)) {
  throw new Error('rule_id must be kebab-case (got: ' + ruleId + ')');
}

const timestamp = new Date().toISOString().replace(/[^0-9]/g, '').slice(0, 14);
const branchName = `aisha/static-defense/${action}-${ruleId}-${timestamp.slice(8, 14)}`;

return [{
  json: {
    rule_id: ruleId,
    action,
    approver: approver || null,
    branch_name: branchName,
    timestamp,
    requested_at: new Date().toISOString(),
  },
}];

// Generate .semgrep/aisha-rules.yml content from the active rules.
//
// MIRRORS scripts/gen-static-defense.mjs renderSemgrepYaml() exactly — the
// two paths MUST produce byte-identical output so the static-defense-
// generator-integrity gate (which compares committed YAML against the
// from-seed-rendered version) doesn't fail.
//
// Drift between this Code node and the script is detected by gate test
// static-defense-committer-flow.gate.test.ts.

const rules = $('Fetch Active Rules').first().json;
if (!Array.isArray(rules)) {
  throw new Error('Expected array of rules from aisha_get_active_static_defense_rules, got: ' + typeof rules);
}

const SEMGREP_HEADER = `###############################################################################
# AISHA orchestrator — local Semgrep rules.
#
# AUTO-GENERATED from public.aisha_static_defense_rules table.
# DO NOT EDIT MANUALLY — regenerate via \`npm run gen:static-defense\`.
#
# To add or modify a rule:
#   1. INSERT/UPDATE in aisha_static_defense_rules via Appsmith UI OR
#      RPC propose_static_defense_rule / publish_static_defense_rule
#   2. Run \`npm run gen:static-defense\` locally (needs DB) OR add a new
#      seed-style migration touching aisha_static_defense_rules
#   3. Commit the regenerated YAML. The .aisha/ payload cache stays LOCAL
#      (gitignored) — CI regenerates from the seed migration via --from-seed.
#
# Rule severity convention:
#   ERROR   — blocks the workflow (matches OWASP A-category violations)
#   WARNING — surfaces but doesn't block (style/maintainability)
#   INFO    — informational, for trend tracking
###############################################################################

`;

const semgrepRules = rules.filter((r) => r.category === 'semgrep');
const lines = [SEMGREP_HEADER, 'rules:'];

for (const rule of semgrepRules) {
  lines.push('');
  if (rule.owasp_category) {
    lines.push(`  # ${rule.owasp_category} — ${rule.rule_id}`);
  }
  lines.push(`  - id: ${rule.rule_id}`);

  // pattern-either
  const patterns = Array.isArray(rule.semgrep_pattern) ? rule.semgrep_pattern : null;
  if (patterns && patterns.length > 0) {
    lines.push('    pattern-either:');
    for (const p of patterns) {
      const key = Object.keys(p)[0];
      lines.push(`      - ${key}: ${JSON.stringify(p[key])}`);
    }
  }

  // paths
  if (rule.semgrep_paths && (rule.semgrep_paths.include || rule.semgrep_paths.exclude)) {
    lines.push('    paths:');
    if (rule.semgrep_paths.include) {
      lines.push('      include:');
      for (const inc of rule.semgrep_paths.include) {
        lines.push(`        - ${JSON.stringify(inc)}`);
      }
    }
    if (rule.semgrep_paths.exclude) {
      lines.push('      exclude:');
      for (const exc of rule.semgrep_paths.exclude) {
        lines.push(`        - ${JSON.stringify(exc)}`);
      }
    }
  }

  // message (block scalar)
  if (rule.semgrep_message) {
    lines.push('    message: |');
    for (const msgLine of rule.semgrep_message.split('\n')) {
      lines.push('      ' + msgLine);
    }
  }

  lines.push(`    severity: ${rule.severity}`);
  if (rule.languages && rule.languages.length > 0) {
    lines.push(`    languages: [${rule.languages.join(', ')}]`);
  }
}

const yamlContent = lines.join('\n') + '\n';
const base64Content = Buffer.from(yamlContent, 'utf-8').toString('base64');

return [{
  json: {
    ...$('Validate Input').first().json,
    yaml_content: yamlContent,
    yaml_base64: base64Content,
    rule_count: semgrepRules.length,
    yaml_path: '.semgrep/aisha-rules.yml',
  },
}];

